"use strict";
// Original offline case. Wrappers preserve the native handset applications.
const mysteryKey='olddays-mystery-01';
let mystery={started:false,paused:false,evidence:[],solved:false,hint:0,pings:0};
try{const p=JSON.parse(localStorage.getItem(mysteryKey)||'null');if(p){mystery.started=p.started===true;mystery.paused=p.paused===true;mystery.solved=p.solved===true;mystery.evidence=['pack','qq','uc','forum'].filter(k=>p.evidence?.includes(k));mystery.hint=Math.min(3,Math.max(0,Number(p.hint)||0));mystery.pings=Math.min(3,Math.max(0,Number(p.pings)||0));}}catch{}
let mysteryPanel='',mysteryFeedback='';
function saveMystery(){try{localStorage.setItem(mysteryKey,JSON.stringify(mystery));}catch{toast('存储不可用，请勿关闭本页');}}
function mysteryButton(panel,label){return `<button class="mystery-link" data-mystery="${panel}">${label}</button>`;}
function mysteryCollect(key){if(!mystery.started||!['pack','qq','uc','forum'].includes(key))return false;if(!mystery.evidence.includes(key))mystery.evidence.push(key);saveMystery();return true;}
function mysterySolve(code,who){if(mystery.evidence.length!==4)return '线索还没有齐，请先核对手机包、QQ、UC和论坛。';if(code!=='0817'||who!=='owner')return '时间或归还对象不对，再核对失物招领和离线留言。';mystery.solved=true;saveMystery();return '结案：这是小夏自己的备份包。她把手机留在修理铺，托阿北取回；0817是失物登记日期，不是下载收费代码。你替一段没发出去的告别，找到了收件人。';}
function mysteryMarkup(){const titles={pack:'手机包 / 夏末备份.zip',qq:'QQ / 阿北的离线消息',uc:'UC / 旧城失物招领',forum:'论坛 / 最后一封信'};const body={pack:'文件清单：夏末.jpg、留言.txt、失物登记.url。留言：不要把手机包交给下载站。我把最后一封信放在“旧城失物招领”；阿北知道我为什么没回学校。壁纸背面的铅笔字：08月，等一个迟到的人。',qq:'阿北（离线） 23:17：小夏不是失踪，她转学了。手机落在修理铺，我答应替她取。她的备份包只给原机主，别给收费下载商。她在论坛叫“夏末未眠”。去UC搜“旧城失物招领”，登记那天就是密码。',uc:'旧城失物招领 / 缓存页：8月17日，蓝色手机一部，寄存于修理铺。领取须核对备份留言与论坛署名。站长补记：下载站声称购买了全部资料，但没有原机主授权。此页是案件虚构网页。',forum:'旧城BBS / 夏末未眠 / 8月17日：明天转学，没来得及告别。手机修好后请阿北替我取，我会回来领。备份只留给我自己。2楼阿北：收到，等你来取。3楼下载商：打包卖彩铃吧。楼主回复：不卖，也别转给陌生人。'};
if(titles[mysteryPanel])return `<section class="mystery-paper"><small>原创案件 · 本机剧情</small><h3>${titles[mysteryPanel]}</h3><p>${body[mysteryPanel]}</p>${mysteryButton('collect:'+mysteryPanel,'记入线索簿')}${mysteryButton('notebook','查看线索簿')}${mysteryButton('close','返回应用')}</section>`;
return `<section class="mystery-paper"><small>隐藏案件 01 / 原创离线解谜</small><h3>夏末未送达</h3><p>${mystery.started?'陌生短信、备份手机包、离线好友和一张旧帖子，谁才是资料的主人？':'这部旧手机里，有一封迟到了很多年的短信。愿意打开吗？'}</p>${!mystery.started?mysteryButton('start','接收陌生短信 / 开始案件'):`<p>线索 ${mystery.evidence.length}/4 · ${mystery.solved?'已结案':'调查中'}</p><ul>${mystery.evidence.map(k=>`<li>${titles[k]}</li>`).join('')}</ul><p>去短信翻手机包，在QQ找阿北，在UC搜索旧城失物招领，再到社区读夏末未眠的帖子。</p>${mysteryFeedback?`<p class="mystery-result" role="status">${mysteryFeedback}</p>`:''}<form data-mystery-solve><label>登记日期（四位数）<input name="code" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required></label><label>手机包应该交给谁？<select name="who"><option value="">选择归还对象</option><option value="seller">收费下载商</option><option value="owner">原机主小夏（阿北代取）</option><option value="stranger">陌生短信发件人</option></select></label><button>核对推理</button></form>${mystery.solved?'<p>✓ 小夏的备份已归还，告别终于送达。第一案完。</p>':''}${mysteryButton('hint','提示（免费）')}${mystery.hint?`<p>${['','先在短信中打开手机包，点“记入线索簿”。','QQ留言给出搜索词；UC搜“旧城失物招领”。','论坛与UC都写8月17日：0817。原机主拥有备份，阿北只是代取。'][mystery.hint]}</p>`:''}${mysteryButton('pause',mystery.paused?'恢复偶遇短信':'暂停偶遇短信')}${mysteryButton('reset','重开案件（再点一次确认）')}`}${mysteryButton('close','返回应用')}<small>存档只在当前浏览器；不发送真实短信、不扣话费。</small></section>`;}
const mysteryBaseSms=phoneSmsMarkup,mysteryBaseQQ=phoneQQMarkup,mysteryBaseUC=phoneUCMarkup,mysteryBaseForum=phoneCommunityMarkup;
function mysteryOverlay(base,extra){return mysteryPanel?mysteryMarkup():extra+base();}
phoneSmsMarkup=function(){return mysteryOverlay(mysteryBaseSms,(smsView==='compose'||smsView==='message')?'':`<div class="mystery-incoming">✉ 未知发件人 · 23:17<br>${mystery.started?'你收到的手机包还在吗？别急着交给下载站。':'一封没有署名的旧短信'}${mysteryButton(mystery.started?'pack':'notebook',mystery.started?'打开附件：夏末备份.zip':'查看陌生短信')}${mystery.started?mysteryButton('notebook','调查记录'):''}${mystery.pings?'<p>后续来信：'+['阿北的头像一直灰着，留言还在。','旧城的登记簿，不一定要联网才看得到。','帖子里的人说了什么，比下载商的广告更可靠。'].slice(0,mystery.pings).join('<br>')+'</p>':''}</div>`);};
phoneQQMarkup=function(){return mysteryOverlay(mysteryBaseQQ,mystery.started?mysteryButton('qq','阿北 [离线留言] · 夏末手机的事'): '');};
phoneUCMarkup=function(){return mysteryOverlay(mysteryBaseUC,mystery.started&&/旧城|失物|夏末/.test(ucQuery)?mysteryButton('uc','搜索结果：旧城失物招领 / 8月登记缓存'): '').replace('没有找到，试试“小说”或“新闻”。',mystery.started&&/旧城|失物|夏末/.test(ucQuery)?'已找到案件缓存，点上方搜索结果阅读。':'没有找到，试试“小说”或“新闻”。');};
phoneCommunityMarkup=function(){return mysteryOverlay(mysteryBaseForum,mystery.started?mysteryButton('forum','[旧帖] 夏末未眠：最后一封信 / 8月17日'): '');};
let mysteryResetArmed=false;
document.addEventListener('click',e=>{const b=e.target.closest('[data-mystery]');if(!b)return;e.preventDefault();const action=b.dataset.mystery;if(action==='start'){mystery.started=true;saveMystery();mysteryPanel='pack';}else if(action.startsWith('collect:')){mysteryCollect(action.split(':')[1]);mysteryFeedback='';toast('已记入线索簿');mysteryPanel='notebook';}else if(action==='pause'){mystery.paused=!mystery.paused;saveMystery();}else if(action==='hint'){mystery.hint=Math.min(3,mystery.hint+1);saveMystery();}else if(action==='reset'){if(!mysteryResetArmed){mysteryResetArmed=true;toast('再点一次“重开案件”清除本案进度');return;}mystery={started:false,paused:false,evidence:[],solved:false,hint:0,pings:0};saveMystery();mysteryFeedback='';mysteryResetArmed=false;mysteryPanel='notebook';}else mysteryPanel=action==='close'?'':action;refreshPhone();});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-mystery-solve]'))return;e.preventDefault();const f=new FormData(e.target);const result=mysterySolve(String(f.get('code')||'').trim(),f.get('who'));mysteryFeedback=result;refreshPhone();toast(mystery.solved?'案件已完成':'已核对，请查看推理结果');});
// Active-page encounters only: capped, persisted, no system push or background messages.
setInterval(()=>{if(document.hidden||!mystery.started||mystery.paused||mystery.solved||mystery.pings>=3)return;mystery.pings++;saveMystery();toast(['叮：陌生短信——阿北的头像一直灰着，留言还在。','叮：陌生短信——旧城的登记簿，不一定要联网才看得到。','叮：陌生短信——帖子里的人说了什么，比下载商的广告更可靠。'][mystery.pings-1]);},180000);
